import React, { useState, useEffect } from 'react';
import {
  View, Text, TouchableOpacity, TextInput, StyleSheet,
  Alert, Linking
} from 'react-native';
import { useIsFocused } from '@react-navigation/native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';

import { useAuth } from '../../hooks/useAuth';
import { useClassroom } from '../../hooks/useClassroom';
import { supabase } from '../../lib/supabase';
import { colors, spacing, radius } from '../../theme';
import { Button, Input, LoadingScreen, Divider } from '../../components/ui';
import { ChildAvatar } from '../../components/ChildAvatar';
import { ClassroomSwitcher } from '../../components/ClassroomSwitcher';
import { DatePickerField } from '../../components/DatePickerField';


// ─── ADD CHILD FORM ───────────────────────────────────────────────────────────
function AddChildForm({ classroomId, onAdded }) {
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName]   = useState('');
  const [dob, setDob]             = useState('');
  const [saving, setSaving]       = useState(false);

  async function handleAdd() {
    if (!firstName.trim()) {
      Alert.alert('Required', "Please enter the child's first name.");
      return;
    }
    setSaving(true);
    const { error } = await supabase.from('children').insert({
      classroom_id: classroomId,
      first_name: firstName.trim(),
      last_name: lastName.trim(),
      date_of_birth: dob || null,
    });
    setSaving(false);
    if (error) {
      Alert.alert('Error', error.message);
    } else {
      setFirstName(''); setLastName(''); setDob('');
      onAdded();
    }
  }

  return (
    <View style={styles.formCard}>
      <Text style={styles.formTitle}>Add a child</Text>
      <Input
        label="First name *"
        value={firstName}
        onChangeText={setFirstName}
        placeholder="e.g. Emma"
      />
      <Input
        label="Last name"
        value={lastName}
        onChangeText={setLastName}
        placeholder="e.g. Smith"
      />
      <DatePickerField
        label="Date of birth (optional)"
        value={dob}
        onChange={setDob}
      />
      <Button label="Add child" onPress={handleAdd} loading={saving} style={{ marginTop: spacing.sm }} />
    </View>
  );
}

// ─── INVITE PARENT FORM ───────────────────────────────────────────────────────
function InviteParentForm({ classroomId, children }) {
  const [email, setEmail]     = useState('');
  const [childId, setChildId] = useState(children[0]?.id || '');
  const [sending, setSending] = useState(false);

  async function handleInvite() {
    if (!email.trim()) {
      Alert.alert('Required', "Please enter the parent's email address.");
      return;
    }
    if (!childId) {
      Alert.alert('Required', 'Please select a child to link this parent to.');
      return;
    }
    setSending(true);

    const { data: existing } = await supabase
      .from('profiles')
      .select('id, full_name')
      .eq('email', email.trim().toLowerCase())
      .single();

    if (existing) {
      const { error } = await supabase
        .from('parent_children')
        .upsert(
          { parent_id: existing.id, child_id: childId },
          { onConflict: 'parent_id,child_id' }
        );
      setSending(false);
      if (error) { Alert.alert('Error', error.message); return; }
      const child = children.find(c => c.id === childId);
      Alert.alert('Linked ✓', `${existing.full_name} has been linked to ${child?.first_name}.`);
      setEmail('');
    } else {
      const { error } = await supabase.auth.signInWithOtp({
        email: email.trim().toLowerCase(),
        options: { data: { pending_child_id: childId, role: 'parent' }, shouldCreateUser: true },
      });
      setSending(false);
      if (error) { Alert.alert('Error', error.message); return; }
      const child = children.find(c => c.id === childId);
      Alert.alert(
        'Invite sent ✓',
        `An invitation email has been sent to ${email.trim()}.\n\nOnce they sign up, link them to ${child?.first_name} from this screen.`
      );
      setEmail('');
    }
  }

  return (
    <View style={styles.formCard}>
      <Text style={styles.formTitle}>Invite a parent</Text>

      <Text style={styles.fieldLabel}>Link to child</Text>
      <View style={styles.childPicker}>
        {children.map(c => (
          <TouchableOpacity
            key={c.id}
            onPress={() => setChildId(c.id)}
            style={[styles.childPickerBtn, c.id === childId && styles.childPickerBtnSelected]}
          >
            <Text style={[styles.childPickerText, c.id === childId && { color: colors.primary, fontWeight: '600' }]}>
              {c.first_name}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      <Input
        label="Parent's email address"
        value={email}
        onChangeText={setEmail}
        placeholder="parent@email.com"
        keyboardType="email-address"
      />
      <Button label="Send invite" onPress={handleInvite} loading={sending} />
    </View>
  );
}

// ─── MAIN SCREEN ──────────────────────────────────────────────────────────────
export default function ManageScreen({ navigation }) {
  const { profile }                   = useAuth();
  const { active: activeClassroom, classrooms, reload: reloadClassrooms, leaveClassroom } = useClassroom();
  const [children, setChildren]       = useState([]);
  const [parents, setParents]         = useState([]);
  const [loading, setLoading]         = useState(true);
  const [tab, setTab]                 = useState('children');
  const [searchQuery, setSearchQuery] = useState('');

  // Classroom editing
  const [editingClassroom, setEditingClassroom] = useState(false);
  const [classroomName, setClassroomName]       = useState('');
  const [classroomAge, setClassroomAge]         = useState('');
  const [savingClassroom, setSavingClassroom]   = useState(false);

  async function load() {
    if (!profile?.classroom_id) return;
    setLoading(true);

    const { data: kids } = await supabase
      .from('children')
      .select('*')
      .eq('classroom_id', profile.classroom_id)
      .order('first_name');

    setChildren(kids || []);

    if (kids?.length) {
      const { data: links } = await supabase
        .from('parent_children')
        .select('parent:profiles(id, full_name, email, phone), child:children(id, first_name)')
        .in('child_id', kids.map(k => k.id));
      setParents(links || []);
    }

    setLoading(false);
  }

  const isFocused = useIsFocused();

  useEffect(() => {
    if (isFocused && profile) load();
  }, [isFocused, profile?.classroom_id]);

  // Remove the old focus listener useEffect

  async function removeChild(child) {
    Alert.alert(
      'Remove child',
      `Remove ${child.first_name} ${child.last_name} from the classroom? Their log history will be kept.`,
      [
        { text: 'Cancel', style: 'cancel' },
        { text: 'Remove', style: 'destructive', onPress: async () => {
          await supabase.from('children').delete().eq('id', child.id);
          load();
        }},
      ]
    );
  }

  async function unlinkParent(parentId, childId) {
    Alert.alert("Unlink parent", "Remove this parent's access to this child?", [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Unlink', style: 'destructive', onPress: async () => {
        await supabase.from('parent_children').delete().eq('parent_id', parentId).eq('child_id', childId);
        load();
      }},
    ]);
  }

  function startEditClassroom() {
    setClassroomName(activeClassroom?.name || '');
    setClassroomAge(activeClassroom?.age_group || '');
    setEditingClassroom(true);
  }

  async function saveClassroom() {
    if (!classroomName.trim()) {
      Alert.alert('Required', 'Please enter a classroom name.');
      return;
    }
    setSavingClassroom(true);
    const { error } = await supabase
      .from('classrooms')
      .update({ name: classroomName.trim(), age_group: classroomAge.trim() || null })
      .eq('id', activeClassroom.id);
    setSavingClassroom(false);
    if (error) {
      Alert.alert('Error', error.message);
    } else {
      setEditingClassroom(false);
      await reloadClassrooms();
    }
  }

  function handleDeleteClassroom() {
    if (children.length > 0) {
      Alert.alert(
        'Cannot delete',
        `This classroom still has ${children.length} children. Move or remove all children first before deleting the classroom.`
      );
      return;
    }
    Alert.alert(
      `Delete "${activeClassroom?.name}"?`,
      'This will permanently remove this classroom. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete', style: 'destructive',
          onPress: async () => {
            await supabase.from('classrooms').delete().eq('id', activeClassroom.id);
            await leaveClassroom(activeClassroom.id);
            await reloadClassrooms();
          },
        },
      ]
    );
  }

  if (loading) return <LoadingScreen />;

  return (
    <KeyboardAwareScrollView
      style={styles.container}
      contentContainerStyle={styles.content}
      enableOnAndroid
      extraScrollHeight={20}
      keyboardShouldPersistTaps="handled"
    >
      <Text style={styles.pageTitle}>Manage classroom</Text>

      <ClassroomSwitcher />

      {/* Tabs */}
      <View style={styles.tabs}>
        {['children', 'parents'].map(t => (
          <TouchableOpacity
            key={t}
            onPress={() => { setTab(t); setSearchQuery(''); }}
            style={[styles.tab, tab === t && styles.tabSelected]}
          >
            <Text style={[styles.tabText, tab === t && styles.tabTextSelected]}>
              {t === 'children'
                ? ` Children (${children.length})`
                : `‍‍ Parents (${parents.length})`}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {tab === 'children' ? (
        <>
          {children.length > 5 && (
            <View style={styles.searchBar}>
              <Text style={styles.searchIcon}></Text>
              <TextInput
                style={styles.searchInput}
                value={searchQuery}
                onChangeText={setSearchQuery}
                placeholder="Search by name..."
                placeholderTextColor={colors.textMuted}
                autoCorrect={false}
              />
              {searchQuery.length > 0 && (
                <TouchableOpacity onPress={() => setSearchQuery('')} style={styles.searchClear}>
                  <Text style={styles.searchClearText}>✕</Text>
                </TouchableOpacity>
              )}
            </View>
          )}
          {children.length > 0 && (
            <View style={styles.listCard}>
              {children
                .filter(child => {
                  if (!searchQuery.trim()) return true;
                  const q = searchQuery.toLowerCase().trim();
                  return `${child.first_name} ${child.last_name}`.toLowerCase().includes(q);
                })
                .map((child, i) => (
                <View key={child.id}>
                  {i > 0 && <Divider />}
                  <TouchableOpacity
                    style={styles.listRow}
                    onPress={() => navigation.navigate('ChildProfile', { child })}
                    activeOpacity={0.7}
                  >
                    <ChildAvatar child={child} size={40} />
                    <View style={styles.listInfo}>
                      <Text style={styles.listName}>{child.first_name} {child.last_name}</Text>
                      {child.date_of_birth && (
                        <Text style={styles.listSub}>Born {child.date_of_birth}</Text>
                      )}
                    </View>
                    <Text style={styles.chevron}>›</Text>
                  </TouchableOpacity>
                </View>
              ))}
            </View>
          )}
          <AddChildForm classroomId={profile.classroom_id} onAdded={load} />
        </>
      ) : (
        <>
          {parents.length > 5 && (
            <View style={styles.searchBar}>
              <Text style={styles.searchIcon}></Text>
              <TextInput
                style={styles.searchInput}
                value={searchQuery}
                onChangeText={setSearchQuery}
                placeholder="Search parents or children..."
                placeholderTextColor={colors.textMuted}
                autoCorrect={false}
              />
              {searchQuery.length > 0 && (
                <TouchableOpacity onPress={() => setSearchQuery('')} style={styles.searchClear}>
                  <Text style={styles.searchClearText}>✕</Text>
                </TouchableOpacity>
              )}
            </View>
          )}
          {parents.length > 0 && (
            <View style={styles.listCard}>
              {parents
                .filter(link => {
                  if (!searchQuery.trim()) return true;
                  const q = searchQuery.toLowerCase().trim();
                  const parentName = (link.parent?.full_name || '').toLowerCase();
                  const childName = (link.child?.first_name || '').toLowerCase();
                  return parentName.includes(q) || childName.includes(q);
                })
                .map((link, i) => (
                <View key={`${link.parent?.id}-${link.child?.id}`}>
                  {i > 0 && <Divider />}
                  <View style={styles.listRow}>
                    <View style={[styles.avatar, { backgroundColor: colors.purpleLight }]}>
                      <Text style={[styles.avatarText, { color: colors.purple }]}>
                        {link.parent?.full_name?.[0] || '?'}
                      </Text>
                    </View>
                    <View style={styles.listInfo}>
                      <Text style={styles.listName}>{link.parent?.full_name}</Text>
                      <Text style={styles.listSub}>
                        {link.parent?.email} · {link.child?.first_name}
                      </Text>
                      {link.parent?.phone ? (
                        <TouchableOpacity
                          onPress={() => Linking.openURL(`tel:${link.parent.phone}`)}
                          style={styles.callRow}
                        >
                          <Text style={styles.callIcon}></Text>
                          <Text style={styles.callText}>{link.parent.phone}</Text>
                        </TouchableOpacity>
                      ) : (
                        <Text style={styles.noPhone}>No phone on file</Text>
                      )}
                    </View>
                    <TouchableOpacity
                      onPress={() => unlinkParent(link.parent?.id, link.child?.id)}
                      style={styles.removeBtn}
                    >
                      <Text style={styles.removeBtnText}>Unlink</Text>
                    </TouchableOpacity>
                  </View>
                </View>
              ))}
            </View>
          )}
          {children.length > 0
            ? <InviteParentForm classroomId={profile.classroom_id} children={children} />
            : <Text style={styles.emptyNote}>Add children first before inviting parents.</Text>
          }
        </>
      )}

      <View style={{ height: spacing.xxxl }} />
    </KeyboardAwareScrollView>
  );
}

