              <Text style={[styles.filterText, filter === f.key && styles.filterTextActive]}>
                {f.label} ({f.count})
              </Text>
            </TouchableOpacity>
          ))}
        </View>
      )}

      {/* Search bar */}
      {children.length > 5 && (
        <View style={styles.searchBar}>
          <Text style={styles.searchIcon}></Text>
          <TextInput
            style={styles.searchInput}
            value={searchQuery}
            onChangeText={setSearchQuery}
            placeholder="Search by name..."
            placeholderTextColor={colors.textMuted}
            autoCorrect={false}
          />
          {searchQuery.length > 0 && (
            <TouchableOpacity onPress={() => setSearchQuery('')} style={styles.searchClear}>
              <Text style={styles.searchClearText}>✕</Text>
            </TouchableOpacity>
          )}
        </View>
      )}

      <FlatList
        data={children.filter(c => {
          // Search filter
          const query = searchQuery.toLowerCase().trim();
          if (query) {
            const fullName = `${c.first_name} ${c.last_name}`.toLowerCase();
            if (!fullName.includes(query)) return false;
          }
          // Status filter
          if (filter === 'all') return true;
          const s = logStatus[c.id];
          if (filter === 'sent') return s?.sent;
          if (filter === 'pending') return !s?.sent;
          return true;
        })}
        keyExtractor={c => c.id}
        renderItem={renderChild}
        contentContainerStyle={styles.list}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={() => { setRefreshing(true); load(); }} tintColor={colors.primary} />
        }
        ListEmptyComponent={
          <EmptyState icon="" message={"No children in your classroom yet.\nGo to Settings → Manage classroom to add them."} />
        }
      />
    </View>
  );
}

